export function getStateViewBox(sigla: string): StateViewBoxData | null {
  return BRAZIL_STATE_VIEWBOXES[sigla] || null;
}

export function getCityViewBox(x: number, y: number, size = 95): StateViewBoxData {
  const clampedX = Math.max(0, Math.min(800 - size, x - size / 2));
  const clampedY = Math.max(0, Math.min(800 - size, y - size / 2));
  return {
    x: clampedX,
    y: clampedY,
    w: size,
    h: size,
    viewBox: `${clampedX.toFixed(1)} ${clampedY.toFixed(1)} ${size} ${size}`,
  };
}
